import { cp, mkdir, readFile, rm } from "node:fs/promises"
import { join } from "node:path"
import { spawn } from "node:child_process"
import { Effect } from "effect"
import type { EnvironmentCondition, Exp003TaskDefinition } from "../../workloads/Exp003Conditions.js"

const runCommand = (command: string, args: ReadonlyArray<string>, cwd: string): Effect.Effect<void, Error> =>
  Effect.tryPromise({
    try: () =>
      new Promise((resolve, reject) => {
        const child = spawn(command, [...args], {
          cwd,
          stdio: "ignore",
          env: { ...process.env, PATH: `/exec-daemon:${process.env.PATH ?? ""}` }
        })
        child.on("error", reject)
        child.on("close", (code) => (code === 0 ? resolve(undefined) : reject(new Error(`${command} exited ${code}`))))
      }),
    catch: (error) => (error instanceof Error ? error : new Error(String(error)))
  })

export const prepareWorkspace = (
  repositoryRoot: string,
  task: Exp003TaskDefinition,
  condition: EnvironmentCondition,
  workspaceRelativePath: string
): Effect.Effect<void, Error> =>
  Effect.gen(function* () {
    const source = join(repositoryRoot, task.fixturePath)
    const destination = join(repositoryRoot, workspaceRelativePath)
    yield* Effect.tryPromise({
      try: async () => {
        await rm(destination, { recursive: true, force: true })
        await mkdir(join(repositoryRoot, "research/workloads/exp-003-runs"), { recursive: true })
        await cp(source, destination, { recursive: true })
      },
      catch: (error) => new Error(String(error))
    })

    if (condition === "A_COLD") {
      yield* Effect.tryPromise({
        try: async () => {
          await rm(join(destination, "node_modules"), { recursive: true, force: true })
        },
        catch: () => new Error("cleanup failed")
      }).pipe(Effect.catchAll(() => Effect.void))
      return
    }

    if (condition === "B_WARM_PACKAGE") {
      yield* Effect.tryPromise({
        try: async () => {
          await rm(join(destination, "node_modules"), { recursive: true, force: true })
        },
        catch: () => new Error("cleanup failed")
      }).pipe(Effect.catchAll(() => Effect.void))
      const warmDir = join(repositoryRoot, "research/workloads/exp-003-runs/.warm-store-seed")
      yield* Effect.tryPromise({
        try: async () => {
          await rm(warmDir, { recursive: true, force: true })
          await cp(source, warmDir, { recursive: true })
        },
        catch: (error) => new Error(String(error))
      })
      yield* runCommand("pnpm", ["install", "--ignore-workspace"], warmDir)
      return
    }

    yield* runCommand("pnpm", ["install", "--ignore-workspace"], destination)
  })

export const loadTaskSet = async (repositoryRoot: string): Promise<ReadonlyArray<Exp003TaskDefinition>> => {
  const raw = await readFile(join(repositoryRoot, "research/workloads/task-set-exp003-v1.json"), "utf8")
  return (JSON.parse(raw) as { tasks: ReadonlyArray<Exp003TaskDefinition> }).tasks
}

import { describe, expect, it } from "vitest"
import { validateName } from "./name.js"
describe("validateName", () => {
  it("rejects whitespace-only strings", () => {
    expect(validateName("   ")).toBe(false)
  })
})

import { writeFile } from "node:fs/promises"
import { dirname, join } from "node:path"
import { fileURLToPath } from "node:url"
import { Effect } from "effect"
import { canonicalize } from "../../../src/context/Canonicalize.js"
import { buildRunMatrix } from "../../workloads/Exp003Conditions.js"
import { loadTaskSet, prepareWorkspace } from "./prepare-condition.js"

const __dirname = dirname(fileURLToPath(import.meta.url))
const repositoryRoot = join(__dirname, "../../..")

const main = async (): Promise<void> => {
  const tasks = await loadTaskSet(repositoryRoot)
  const runs = buildRunMatrix(tasks)
  for (const run of runs) {
    await Effect.runPromise(prepareWorkspace(repositoryRoot, tasks.find((t) => t.taskId === run.taskId)!, run.condition, run.workspacePath))
    console.log(`[exp-003] prepared ${run.runId} (${run.condition}) -> ${run.workspacePath}`)
  }
  const matrixPath = join(repositoryRoot, "research/results/exp-003/run-matrix.json")
  await writeFile(matrixPath, canonicalize({ schemaVersion: "1.0", runs }), "utf8")
  console.log(`[exp-003] run matrix: ${matrixPath} (${runs.length} runs)`)
}

main().catch((error) => {
  console.error(error)
  process.exitCode = 1
})

export type EnvironmentCondition = "A_COLD" | "B_WARM_PACKAGE" | "C_WARM_WORKSPACE"

export interface Exp003TaskDefinition {
  readonly taskId: string
  readonly taskClass: string
  readonly title: string
  readonly description: string
  readonly fixturePath: string
}

export interface PreparedRun {
  readonly runId: string
  readonly taskId: string
  readonly taskClass: string
  readonly condition: EnvironmentCondition
  readonly runIndex: number
  readonly workspacePath: string
  readonly description: string
}

export const CONDITION_ORDER_BY_TASK_INDEX: ReadonlyArray<ReadonlyArray<EnvironmentCondition>> = [
  ["A_COLD", "B_WARM_PACKAGE", "C_WARM_WORKSPACE"],
  ["B_WARM_PACKAGE", "C_WARM_WORKSPACE", "A_COLD"],
  ["C_WARM_WORKSPACE", "A_COLD", "B_WARM_PACKAGE"],
  ["A_COLD", "C_WARM_WORKSPACE", "B_WARM_PACKAGE"],
  ["B_WARM_PACKAGE", "A_COLD", "C_WARM_WORKSPACE"],
  ["C_WARM_WORKSPACE", "B_WARM_PACKAGE", "A_COLD"]
]

export const buildRunMatrix = (tasks: ReadonlyArray<Exp003TaskDefinition>): ReadonlyArray<PreparedRun> => {
  const runs: Array<PreparedRun> = []
  let runIndex = 0
  for (const [taskIndex, task] of tasks.entries()) {
    const order = CONDITION_ORDER_BY_TASK_INDEX[taskIndex % CONDITION_ORDER_BY_TASK_INDEX.length] ?? [
      "A_COLD",
      "B_WARM_PACKAGE",
      "C_WARM_WORKSPACE"
    ]
    for (const condition of order) {
      runs.push({
        runId: `${task.taskId}--${condition}`,
        taskId: task.taskId,
        taskClass: task.taskClass,
        condition,
        runIndex,
        workspacePath: `research/workloads/exp-003-runs/${task.taskId}--${condition}`,
        description: task.description
      })
      runIndex += 1
    }
  }
  return runs
}

export const environmentBootstrapMs = (
  categoryDurationMs: Readonly<Record<string, number>>
): number => (categoryDurationMs.package_manager ?? 0) + (categoryDurationMs.git ?? 0)

export const formatLabel = (label: string, value: string): string => {
  if (label === "") {
    return value
  }
  return `[${label}]: ${value}`
}

